mapper.select:
SELECT pi.college_id AS collegeId, c.college_name AS collegeName, ROUND(AVG(pi.similarity_rate), 2) AS avgRate, COUNT(*) AS total FROM paper_info pi LEFT JOIN college c ON pi.college_id = c.id WHERE pi.is_deleted = 0 AND pi.similarity_rate IS NOT NULL
AND 1 = 0
AND pi.college_id = #{scope.collegeId}
AND pi.major_id = #{scope.majorId}
AND pi.teacher_id = #{scope.teacherId}
AND pi.student_id = #{scope.studentId}
GROUP BY pi.college_id, c.college_name
